/** Full logo as on remocn.dev: R mark + "emocn" in Manrope 600. */
function RemocnLogo({ fontSize, color }: { fontSize: number; color: string }) {
  return (
    <div
      style={{
        display: "flex",
        alignItems: "baseline",
        color,
        fontFamily: sans,
        fontWeight: 600,
        fontSize,
        letterSpacing: "-0.025em",
        lineHeight: 1,
      }}
    >
      <svg
        viewBox="0 0 124.06 134.26"
        style={{ height: "0.76em", width: "auto" }}
        aria-hidden
      >
        <path fill="currentColor" d={REMOCN_R_PATH} />
      </svg>
      <span style={{ marginLeft: "0.04em" }}>emocn</span>
    </div>
  );
}

interface GlassLensProps {
  /** Headline lines, set big on the left. */
  lines?: string[];
  /** Set the last headline line in italic. */
  italicLast?: boolean;
  /** Which word the lens stops on first: line index and word index. */
  focus?: { line: number; word: number };
  /** Label inside the pill the lens becomes. */
  cta?: string;
  /** Replaces the remocn logo above the headline. */
  logo?: React.ReactNode;
  /** Screenshot for the product pane. */
  src?: string;
  /** Custom content for the product pane (wins over `src`). */
  children?: React.ReactNode;
  accent?: string;
  /** Title inside the product pane's preview. */
  previewTitle?: string;
  /** How strongly the glass magnifies; 0 for flat glass. */
  magnify?: number;
  /** Color of the headline and logo; overrides the theme ink. */
  ink?: string;
  /** Background fill; "transparent" drops it. */
  background?: string;
  /** Typeface for the headline. Load it yourself; Newsreader by default. */
  fontFamily?: string;
  /** Size of the headline, pane and lens, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  /** Film grain over the scene. */
  grain?: boolean;
  /** Playback multiplier. */
  speed?: number;
  theme?: "dark" | "light";
}

const midway = (p: number) => p > 5e-4 && p < 1 - 5e-4;

const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const THEMES = {
  dark: {
    bg: "#0A0A0B",
    stage: "rgba(255,255,255,0.06)",
    fg: "#F3F2EF",
    muted: "#8B8A90",
    pane: "#131315",
    paneEdge: "rgba(255,255,255,0.09)",
    block: "rgba(255,255,255,0.06)",
    blockHi: "rgba(255,255,255,0.11)",
    hair: "rgba(255,255,255,0.07)",
    paneShadow: "0 30px 80px -20px rgba(0,0,0,0.9)",
    glassTint: "rgba(255,255,255,0.03)",
    rimHi: 0.85,
    rimLo: 0.22,
    lensShadow: "rgba(0,0,0,0.7)",
    edgeLine: "rgba(255,255,255,0.05)",
    innerShade: "rgba(0,0,0,0.3)",
    grain: 0.06,
  },
  light: {
    bg: "#F5F4F0",
    stage: "rgba(255,255,255,0.85)",
    fg: "#121214",
    muted: "#6E6C67",
    pane: "#FFFFFF",
    paneEdge: "rgba(18,18,20,0.08)",
    block: "rgba(18,18,20,0.05)",
    blockHi: "rgba(18,18,20,0.09)",
    hair: "rgba(18,18,20,0.07)",
    paneShadow: "0 30px 70px -24px rgba(60,52,40,0.28)",
    glassTint: "rgba(255,255,255,0.07)",
    rimHi: 1,
    rimLo: 0.45,
    lensShadow: "rgba(60,52,40,0.22)",
    edgeLine: "rgba(18,18,20,0.07)",
    innerShade: "rgba(60,52,40,0.12)",
    grain: 0.045,
  },
} as const;

type Palette = (typeof THEMES)[keyof typeof THEMES];

/** gradients.sh "silk" (bg #030308; #3b3fd8, #f3d6c0, #8a7bff). */
function silk(t: number) {
  const a = 172 + Math.sin(t / 50) * 3;
  const x = 45 + Math.sin(t / 61) * 4;
  return [
    `linear-gradient(${a}deg, transparent 22%, rgba(243,214,192,0.62) 34%, rgba(59,63,216,0.72) 46%, transparent 82%)`,
    `radial-gradient(70% 45% at ${x}% 42%, rgba(138,123,255,0.4), transparent 70%)`,
    "#030308",
  ].join(", ");
}

const HEAD_TRACK = -0.022;
const CTA_TRACK = -0.015;

interface Face {
  family: string;
  italic?: boolean;
  weight: number;
  track: number;
}

let measureCtx: CanvasRenderingContext2D | null = null;
/** Advance width in em with the loaded face (a rough estimate before that). */
function measureEm(text: string, f: Face) {
  if (!measureCtx && typeof document !== "undefined") {
    measureCtx = document.createElement("canvas").getContext("2d");
  }
  const tracking = f.track * [...text].length;
  if (!measureCtx) return text.length * 0.48 + tracking;
  measureCtx.font = `${f.italic ? "italic " : ""}${f.weight} 100px "${f.family}"`;
  return measureCtx.measureText(text).width / 100 + tracking;
}

/** Holds the frame until the faces are in, so layout is measured once, right. */
function useFontsReady(fontFamily: string) {
  const [handle] = useState(() => delayRender("glass-lens: fonts"));
  // the family whose faces are in, so a new `fontFamily` re-measures once loaded
  const [ready, setReady] = useState<string | null>(null);
  useEffect(() => {
    let live = true;
    Promise.all([
      manrope.waitUntilDone(),
      serifUpright.waitUntilDone(),
      serifItalic.waitUntilDone(),
      document.fonts.load(`400 100px "${fontFamily}"`),
      document.fonts.load(`italic 400 100px "${fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (live) setReady(fontFamily);
      });
    return () => {
      live = false;
    };
  }, [fontFamily]);
  useEffect(() => {
    if (ready !== null) continueRender(handle);
  }, [ready, handle]);
  return ready;
}

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={7}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

interface Layout {
  u: number;
  left: number;
  top: number;
  size: number;
  lineH: number;
  pane: { x: number; y: number; w: number; h: number };
  clip: { x: number; y: number };
  ctaY: number;
}

function useLayout(lineEms: number[]): Layout {
  const { width, height } = useSceneConfig();
  const u = height / 720;
  const left = width * 0.075;
  const longest = Math.max(...lineEms);
  const size = Math.min(108 * u, (width * 0.43) / Math.max(longest, 1));
  const lineH = size * 1.02;
  const top = height * 0.5 - (lineEms.length * lineH) / 2 - 30 * u;
  const pane = {
    x: width * 0.535,
    y: height * 0.17,
    w: width * 0.4,
    h: height * 0.66,
  };
  // the accent clip in the placeholder timeline: the second lens stop
  const clip = {
    x: pane.x + pane.w * 0.47,
    y: pane.y + pane.h * 0.775,
  };
  return {
    u,
    left,
    top,
    size,
    lineH,
    pane,
    clip,
    ctaY: top + lineEms.length * lineH + 60 * u,
  };
}

/** The abstracted product: a pane of hairlines, a preview and a timeline. */
function Placeholder({
  w,
  h,
  u,
  p,
  accent,
  t,
  previewTitle,
}: {
  w: number;
  h: number;
  u: number;
  p: Palette;
  accent: string;
  t: number;
  previewTitle: string;
}) {
  const pad = w * 0.05;
  const bar = (x: number, y: number, bw: number, bh: number, c: string) => (
    <div
      style={{
        position: "absolute",
        left: x,
        top: y,
        width: bw,
        height: bh,
        borderRadius: bh / 2,
        background: c,
      }}
    />
  );
  const clips = [
    [0.05, 0.26, 0],
    [0.33, 0.28, 1],
    [0.63, 0.32, 0],
    [0.05, 0.4, 0],
    [0.47, 0.22, 0],
    [0.71, 0.24, 0],
  ];
  const head = (w - pad * 2) * interpolate(t, [20, 190], [0.38, 0.62], CLAMP);
  // Layout rounds a box's edges to whole pixels, so a playhead eased by
  // `left` steps unevenly; while it moves it sits where it stops and travels
  // by transform. At either end it keeps the plain layout.
  const headRest = (w - pad * 2) * 0.62;
  const headMoving = t > 20 && t < 190;
  return (
    <>
      {bar(pad, h * 0.045, w * 0.16, 9 * u, p.blockHi)}
      {bar(w - pad - w * 0.1, h * 0.045, w * 0.1, 9 * u, p.block)}
      <div
        style={{
          position: "absolute",
          left: 0,
          right: 0,
          top: h * 0.11,
          height: 1,
          background: p.hair,
        }}
      />
      {/* the preview: the film being cut, lit by the silk sheen */}
      <div
        style={{
          position: "absolute",
          left: pad,
          top: h * 0.155,
          width: w - pad * 2,
          height: h * 0.47,
          borderRadius: 10 * u,
          background: silk(t),
          overflow: "hidden",
        }}
      >
        <div
          style={{
            position: "absolute",
            left: "8%",
            bottom: "16%",
            fontFamily: serif,
            fontStyle: "italic",
            fontWeight: 400,
            fontSize: 34 * u,
            letterSpacing: "-0.02em",
            lineHeight: 1,
            color: "#FFF8F2",
          }}
        >
          {previewTitle}
        </div>
        <div
          style={{
            position: "absolute",
            left: "8%",
            right: "8%",
            bottom: "8%",
            height: 3 * u,
            borderRadius: 2 * u,
            background: "rgba(255,255,255,0.18)",
          }}
        >
          <div
            style={{
              width: `${interpolate(t, [0, 210], [22, 61], CLAMP)}%`,
              height: "100%",
              borderRadius: 2 * u,
              background: "rgba(255,248,242,0.85)",
            }}
          />
        </div>
      </div>
      {[0, 1].map((row) =>
        clips
          .filter((_, i) => Math.floor(i / 3) === row)
          .map(([x, cw, hi], i) => (
            <div
              key={`${row}-${x}`}
              style={{
                position: "absolute",
                left: pad + (w - pad * 2) * x,
                top: h * (0.73 + row * 0.1),
                width: (w - pad * 2) * cw - 4 * u,
                height: h * 0.075,
                borderRadius: 6 * u,
                background: hi ? accent : p.block,
                boxShadow: hi ? "none" : `inset 0 0 0 1px ${p.hair}`,
                display: "flex",
                alignItems: "center",
                paddingLeft: 8 * u,
                fontFamily: sans,
                fontSize: 10.5 * u,
                fontWeight: 500,
                color: hi ? "#FFFFFF" : p.muted,
                fontVariantNumeric: "tabular-nums",
                whiteSpace: "nowrap",
                overflow: "hidden",
              }}
            >
              {hi ? "Scene 03 · 4.2s" : i === 0 && row === 0 ? "Intro" : ""}
            </div>
          )),
      )}
      <div
        style={{
          position: "absolute",
          left: pad + (headMoving ? headRest : head),
          top: h * 0.69,
          transform: headMoving
            ? `translateX(${head - headRest}px)`
            : undefined,
          width: Math.max(1, 1.5 * u),
          height: h * 0.25,
          background: p.fg,
          opacity: 0.55,
        }}
      />
    </>
  );
}

/** Everything under the glass. Rendered once flat and once magnified. */
function Scene({
  t,
  lines,
  italicLast,
  logo,
  src,
  children,
  accent,
  p,
  L,
  fg,
  bg,
  fontFamily,
  previewTitle,
  tilted = false,
}: {
  /** An ancestor already carries the tilt; one per chain is enough. */
  tilted?: boolean;
  t: number;
  lines: string[];
  italicLast: boolean;
  logo?: React.ReactNode;
  src?: string;
  children?: React.ReactNode;
  accent: string;
  p: Palette;
  L: Layout;
  fg: string;
  bg: string;
  fontFamily: string;
  previewTitle: string;
}) {
  const glide = useGlide();
  const { width, height } = useSceneConfig();
  const { u } = L;
  const rise = (d: number) =>
    interpolate(t, [d - 8, d + 20], [0, 1], { ...CLAMP, easing: EASE_OUT });
  const paneIn = rise(4);
  return (
    <div
      style={{
        position: "absolute",
