        }}
      />
      <div
        style={{
          position: "absolute",
          left: L.left,
          top: L.top - 64 * u,
          opacity: rise(0),
        }}
      >
        {logo ?? <RemocnLogo fontSize={26 * u} color={fg} />}
      </div>
      {lines.map((line, i) => {
        const italic = italicLast && i === lines.length - 1 && lines.length > 1;
        return (
          <div
            key={line}
            style={{
              position: "absolute",
              left: L.left,
              top: L.top + i * L.lineH,
              height: L.lineH,
              display: "flex",
              alignItems: "center",
              fontFamily,
              fontStyle: italic ? "italic" : "normal",
              fontWeight: 400,
              fontSize: L.size,
              letterSpacing: `${HEAD_TRACK}em`,
              lineHeight: 1,
              color: fg,
              whiteSpace: "pre",
              opacity: rise(i * 3),
              transform: `translateY(${(1 - rise(i * 3)) * 24 * u}px)${glide(!tilted && midway(rise(i * 3)))}`,
            }}
          >
            {line}
          </div>
        );
      })}
      <div
        style={{
          position: "absolute",
          left: L.pane.x,
          top: L.pane.y,
          width: L.pane.w,
          height: L.pane.h,
          borderRadius: 16 * u,
          background: p.pane,
          boxShadow: `inset 0 0 0 1px ${p.paneEdge}, ${p.paneShadow}`,
          overflow: "hidden",
          opacity: paneIn,
          transform: `translateX(${(1 - paneIn) * 40 * u}px)`,
