const ELEMENT_PROP_KEYS = new Set(["theme","cta","previewTitle","italicLast","magnify","accent","fontFamily","ink","background","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  cta: "Start with remocn",
  previewTitle: "Launch day.",
  italicLast: true,
  magnify: 1,
  accent: "#3B5BFD",
  fontFamily: "Newsreader",
  scale: 1,
  delay: 0,
  grain: true,
  speed: 1,
};

type GlassLensElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof GlassLensBase>;

const GlassLensInner = forwardRef<
  HTMLDivElement,
  GlassLensElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<GlassLens>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <GlassLensBase
          {...(componentProps as unknown as ComponentProps<typeof GlassLensBase>)}
        />
      </div>
    </Sequence>
  );
});

export const GlassLens = Interactive.withSchema({
  Component: GlassLensInner,
  componentName: "<GlassLens>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
